create extension if not exists pgcrypto;
create table if not exists campaign_customers (id uuid primary key default gen_random_uuid(), name text not null, email text not null, phone text not null, region text not null, seller_id uuid, created_at timestamptz not null default now(), unique (phone));
create table if not exists campaign_cards (id uuid primary key default gen_random_uuid(), customer_id uuid not null references campaign_customers(id) on delete cascade, campaign_key text not null default 'blue-friday-2026', available_labels integer not null default 0 check (available_labels >= 0), reserved_labels integer not null default 0 check (reserved_labels >= 0), updated_at timestamptz not null default now(), unique (customer_id, campaign_key));
create table if not exists label_ledger (id uuid primary key default gen_random_uuid(), card_id uuid not null references campaign_cards(id) on delete cascade, seller_id uuid, quantity integer not null check (quantity <> 0), action text not null check (action in ('issued','redeemed','reserved','released','adjusted')), order_reference text, note text, created_at timestamptz not null default now());
create index if not exists label_ledger_card_created_idx on label_ledger(card_id, created_at desc);
create table if not exists campaign_settings (campaign_key text primary key, discount_percentage_points_per_ton numeric(8,4) not null default 0.0300, max_discount_percentage_points numeric(8,4), starts_on date not null default date '2026-11-01', ends_on date not null default date '2026-11-30', updated_at timestamptz not null default now());
insert into campaign_settings(campaign_key,discount_percentage_points_per_ton,max_discount_percentage_points) values('blue-friday-2026',0.0300,null) on conflict(campaign_key) do update set discount_percentage_points_per_ton=0.0300,max_discount_percentage_points=null,updated_at=now();
create table if not exists campaign_eligible_products (id uuid primary key default gen_random_uuid(), campaign_key text not null references campaign_settings(campaign_key) on delete cascade, product_code text not null, description text, measure text, active boolean not null default true, created_at timestamptz not null default now(), unique(campaign_key,product_code));
alter table campaign_customers add column if not exists document_type text;
alter table campaign_customers add column if not exists document_number text;
alter table campaign_customers add column if not exists normalized_document text;
alter table campaign_customers add column if not exists account_email text;
create unique index if not exists campaign_customers_document_idx on campaign_customers(normalized_document) where normalized_document is not null;
create table if not exists customer_document_access (id uuid primary key default gen_random_uuid(), account_email text not null, document_type text not null check (document_type in ('cpf','cnpj')), normalized_document text not null, created_at timestamptz not null default now(), unique(account_email,normalized_document));

